customCSS:
.t, .history { color: #8a9199; }
.join { color: #67c605; }
.part, .quit { color: #8a9199; }
.kick, .error { color: #ec420e; }
.notice { color: #ed8515; }
.action { color: #864cc0; }
.mode, .nick, .topic, .server { color: #41b487; }
.highlight { color: #4a5460; background-color: #eceade; border-left: 3px solid #864cc0; padding-left: 8px; }
.reply { color: #8a9199; border-left: 2px solid #3694d0; padding-left: 6px; }
.oper { color: #f9f9f9; background-color: #ed8515; }
.reactions { color: #3694d0; background-color: #eceade; }
.card { background-color: #eceade; border-color: #8a9199; }
.card-title { color: #3694d0; }
.card-desc { color: #8a9199; }
.daychange { color: #8a9199; border-color: #eceade; }
